export const adminHtml = `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Foursday 管理台</title>
  <style nonce="__NONCE__">
    :root{color-scheme:light;--bg:#f4f5f3;--panel:#fff;--ink:#17201d;--muted:#65706c;--line:#dce1de;--accent:#176b51;--accent-soft:#e5f1ec;--danger:#a33939;--warn:#9a6414;--radius:12px;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}
    *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-size:14px}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.5}
    :focus-visible{outline:3px solid #78b7a4;outline-offset:2px}.shell{display:grid;grid-template-columns:220px 1fr;min-height:100vh}.rail{background:#1d2925;color:#eef4f1;padding:26px 18px;position:sticky;top:0;height:100vh}.brand{font-size:18px;font-weight:700;margin:0 10px 30px}.brand small{display:block;color:#aebbb6;font-size:12px;font-weight:400;margin-top:5px}.nav button{display:block;width:100%;border:0;background:transparent;color:#cbd5d1;text-align:left;padding:11px 12px;border-radius:8px;margin:4px 0}.nav button.active,.nav button:hover{background:#31403a;color:#fff}.main{padding:28px 34px 50px;max-width:1440px;width:100%}.top{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:24px}.top h1{font-size:26px;margin:0 0 6px}.sub{color:var(--muted)}.actions{display:flex;gap:8px}.btn{border:1px solid var(--line);background:#fff;color:var(--ink);padding:8px 13px;border-radius:8px}.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}.btn.danger{color:var(--danger)}.statusbar{display:flex;align-items:center;gap:16px;border:1px solid var(--line);background:var(--panel);padding:13px 16px;border-radius:var(--radius);margin-bottom:20px}.dot{width:9px;height:9px;border-radius:50%;background:#87928e}.dot.ok{background:#27835f}.dot.bad{background:#bf4949}.spacer{flex:1}.grid{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));border:1px solid var(--line);border-radius:var(--radius);background:var(--panel);overflow:hidden;margin-bottom:20px}.metric{padding:18px;border-right:1px solid var(--line)}.metric:last-child{border:0}.metric strong{font-size:25px;display:block;margin-top:7px}.section{border:1px solid var(--line);border-radius:var(--radius);background:var(--panel);margin-bottom:18px;overflow:hidden}.section-head{display:flex;justify-content:space-between;align-items:center;padding:15px 17px;border-bottom:1px solid var(--line)}.section-head h2{font-size:16px;margin:0}.section-body{padding:0 17px 15px}.section-hint{padding:0 17px 15px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:760px}th,td{text-align:left;padding:12px 16px;border-bottom:1px solid #edf0ee;vertical-align:top}th{color:var(--muted);font-size:12px;font-weight:600;background:#fafbfa}tr:last-child td{border-bottom:0}.tag{display:inline-block;padding:3px 8px;border-radius:999px;background:#edf0ee;color:#45504c;font-size:12px}.tag.ok{background:var(--accent-soft);color:var(--accent)}.tag.warn{background:#fff2dc;color:var(--warn)}.tag.bad{background:#f8e5e5;color:var(--danger)}.preview{max-width:480px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.row-actions{display:flex;gap:6px;align-items:center}.row-actions button{border:0;background:transparent;color:var(--accent);padding:2px}.review-card{padding:18px 20px}.review-progress{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:16px}.review-message{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f6f5;border:1px solid var(--line);border-radius:8px;padding:14px;line-height:1.65;margin:10px 0 14px}.review-meta{display:flex;flex-wrap:wrap;gap:8px 16px;color:var(--muted);font-size:12px}.review-choice{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:18px}.review-choice .btn{padding:11px;font-weight:600}.empty,.error{padding:36px;text-align:center;color:var(--muted)}.error{color:var(--danger)}.login{max-width:480px;margin:12vh auto;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px}.login h1{margin:0 0 8px}.field{display:block;margin:18px 0}.field span{display:block;margin-bottom:7px;color:var(--muted)}.field input,.field select{width:100%;padding:10px 11px;border:1px solid var(--line);border-radius:8px;background:#fff}.privacy-form{padding:0 17px 18px;display:grid;grid-template-columns:180px minmax(260px,1fr) auto;gap:12px;align-items:end}.privacy-form .field{margin:0}.privacy-code{display:block;overflow-wrap:anywhere;background:#f4f6f5;border:1px solid var(--line);border-radius:7px;padding:9px 11px;margin:8px 0}.hint{font-size:12px;color:var(--muted);line-height:1.6}.hidden{display:none!important}.notice{padding:10px 13px;background:#fff6e6;color:#744d12;border:1px solid #f0d9af;border-radius:8px;margin-bottom:18px}.skeleton{height:16px;background:#e8ebe9;border-radius:5px;animation:pulse 1.2s ease-in-out infinite alternate;margin:14px}@keyframes pulse{to{opacity:.45}}@media(prefers-reduced-motion:reduce){.skeleton{animation:none}}@media(max-width:850px){.shell{display:block}.rail{position:static;height:auto;padding:16px}.brand{margin:0 0 12px}.nav{display:flex;overflow:auto}.nav button{white-space:nowrap;width:auto}.main{padding:20px 16px}.grid{grid-template-columns:1fr 1fr}.metric:nth-child(2){border-right:0}.metric:nth-child(-n+2){border-bottom:1px solid var(--line)}.top{display:block}.actions{margin-top:14px}.privacy-form{grid-template-columns:1fr}.review-progress{align-items:flex-start;flex-direction:column}.review-choice{grid-template-columns:1fr}}
  </style>
  <style nonce="__NONCE__">
    .review-steps{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:18px 0 14px}.review-step{border:1px solid var(--line);border-radius:8px;padding:9px 11px;color:var(--muted);background:#f7f8f7}.review-step strong{display:block;color:inherit;margin-bottom:2px}.review-step.active{border-color:#5d9d88;background:var(--accent-soft);color:var(--accent)}.review-step.complete{border-color:#b9d3ca;color:#315f50}.review-form{border:0;padding:0;margin:16px 0 0;min-width:0}.review-form legend{font-weight:700;padding:0;margin-bottom:10px}.review-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.review-options.three{grid-template-columns:repeat(3,minmax(0,1fr))}.review-option{min-height:42px;text-align:left}.review-option[aria-pressed="true"]{border-color:var(--accent);background:var(--accent-soft);color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}.review-detail{display:block;margin-top:14px}.review-detail span{display:block;margin-bottom:7px;color:var(--muted)}.review-detail textarea{display:block;width:100%;min-height:84px;resize:vertical;padding:10px 11px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink)}.review-detail textarea:focus{border-color:var(--accent)}.review-submit{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:14px}.review-submit .left,.review-submit .right{display:flex;gap:8px;flex-wrap:wrap}.review-inline-error{margin:14px 0 0;padding:10px 12px;border:1px solid #e4bcbc;border-radius:8px;background:#fff3f3;color:var(--danger)}.review-draft{white-space:pre-wrap;overflow-wrap:anywhere;border-left:3px solid #a9c9be;padding:4px 0 4px 12px;line-height:1.65}.task-review-hint{color:var(--muted);font-size:12px;max-width:190px}
    @media(max-width:850px){.review-options,.review-options.three{grid-template-columns:1fr}.review-submit{align-items:stretch;flex-direction:column}.review-submit .left,.review-submit .right{width:100%}.review-submit .btn{flex:1}}
  </style>
</head>
<body>
  <main id="login" class="login">
    <h1>Foursday 管理台</h1><p class="sub">仅限本机访问。令牌只保存在当前标签页。</p>
    <label class="field"><span>只读令牌</span><input id="read-token" type="password" autocomplete="off"></label>
    <label class="field"><span>写入令牌（可选）</span><input id="write-token" type="password" autocomplete="off"></label>
    <button id="login-button" class="btn primary">进入管理台</button>
    <p id="login-error" class="error hidden" role="alert"></p><p class="hint">写入令牌用于暂停、恢复、审批、拒绝和撤销；不填写时仍可安全查看。管理台不提供执行工作计划或发送钉钉消息的入口。</p>
  </main>
  <div id="app" class="shell hidden">
    <aside class="rail"><div class="brand">Foursday<small>本机管理台</small></div><nav class="nav" aria-label="管理栏目"><button data-view="overview" class="active">总览</button><button data-view="tasks">消息草稿</button><button data-view="plans">工作计划</button><button data-view="takeover">人工接管</button><button data-view="quality">判断质量</button><button data-view="operations">运营指标</button><button data-view="targets">监听范围</button><button data-view="capabilities">项目能力</button><button data-view="scoped-pauses">局部暂停</button><button data-view="memories">正式记忆</button><button data-view="privacy">数据删除预览</button><button data-view="health">运行状态</button></nav></aside>
    <section class="main"><header class="top"><div><h1 id="title">总览</h1><div class="sub" id="updated">尚未刷新</div></div><div class="actions"><button id="refresh" class="btn">刷新</button><button id="pause" class="btn danger">暂停系统</button><button id="logout" class="btn">退出</button></div></header><div class="notice">真实发送默认关闭；这里仅管理草稿、审批、记忆和运行状态。</div><div id="content" aria-live="polite"><div class="skeleton"></div><div class="skeleton"></div></div></section>
  </div>
  <script nonce="__NONCE__">
    const state={view:'overview',overview:null,tasks:[],plans:[],takeovers:[],memories:[],scopedPauses:[],targets:null,quality:null,qualitySession:{completed:0,taskId:null,stage:'response',expectedShouldReply:null,responseReasonCode:null,draftAssessment:null,draftReasonCode:null,error:'',submitting:false},operations:null,privacyPreview:null,capabilities:{global:[],projects:[],catalog:[]}};
    const el=(id)=>document.getElementById(id); const esc=(v)=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
    const reviewReasonOptions=[['missed_request','遗漏明确请求'],['closed_loop','闭环消息误触发'],['group_trigger','群聊触发错误'],['manual_replied','人工已经回复'],['context_error','上下文判断错误'],['capability_boundary','能力边界判断错误'],['other','其他']];
    const draftReasonOptions=[['wrong_context','上下文理解错误'],['wrong_recipient','回复对象错误'],['fact_error','事实或信息错误'],['incomplete','遗漏关键信息'],['tone_format','语气或格式不合适'],['unsafe_claim','存在越权、承诺或不安全表述'],['other','其他']];
    function resetQualityReview(taskId=null,expectedShouldReply=null,stage='response'){const completed=state.qualitySession.completed;state.qualitySession={completed,taskId,stage,expectedShouldReply,responseReasonCode:null,draftAssessment:null,draftReasonCode:null,error:'',submitting:false}}
    function syncQualityReview(current){if(state.qualitySession.taskId===current.id)return;const resumeDraft=current.responseReviewUsable===true&&current.expectedShouldReply===true&&current.shouldReply===true&&String(current.draft||'').trim().length>0&&current.draftReviewCurrent!==true;resetQualityReview(current.id,resumeDraft?true:null,resumeDraft?'draft':'response')}
    async function api(path,{method='GET',body,write=false}={}){const headers={Authorization:'Bearer '+sessionStorage.getItem('ai-read')};if(body)headers['Content-Type']='application/json';if(write){const token=sessionStorage.getItem('ai-write');if(!token)throw new Error('需要写入令牌');headers['X-AI-Employee-Write-Token']=token}let r;try{r=await fetch(path,{method,headers,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(10000)})}catch(error){if(error?.name==='TimeoutError')throw new Error('请求超时，请确认服务状态后重试');throw error}let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.error||('请求失败 '+r.status));return data}
    const statusNames={queued:'排队中',processing:'处理中',awaiting_approval:'待审批',no_reply:'无需回复',approved:'已批准',rejected:'已拒绝',sending:'发送中',completed:'已完成',send_unknown:'发送结果待核对',cancelled_manual:'人工已回复',cancelled_operator:'人工已关闭',expired:'已过期',dead:'处理失败',waiting_information:'等待补充信息',continuation_pending:'正在判断补充信息',continued:'已接续原任务',proposed:'待确认',confirmed:'已确认',revoked:'已撤销',failed:'失败',superseded:'已替代',ready:'可执行',executing:'执行中',verifying:'验证中'};
    const tag=(status)=>{const bad=['dead','failed','rejected','send_unknown','revoked'];const warn=['awaiting_approval','queued','proposed','expired','superseded','waiting_information','continuation_pending'];return '<span class="tag '+(bad.includes(status)?'bad':warn.includes(status)?'warn':'ok')+'">'+esc(statusNames[status]||status)+'</span>'};
    const failureLabel=(code)=>({request_timeout:'请求超时',codex_execution_failed:'Codex 执行失败',codex_output_invalid:'草稿结构无效',network_unavailable:'网络不可用',permission_denied:'权限不足',operation_failed:'执行失败'}[code]||'');
    function memorySourceDetails(m){const label={historical_project_import:'历史项目导入',dingtalk_message:'钉钉消息',work_plan:'工作计划',gbrain:'gbrain 知识页'}[m.sourceType]||m.sourceType||'未知';const digest=String(m.sourceId||'');const identity=m.sourceType==='historical_project_import'?(digest.slice(0,12)+(digest.length>12?'…':'')):digest;const historical=m.sourceType==='historical_project_import'?'；源文件：'+esc(m.scope?.sourcePath||'未知')+'；引文摘要：'+esc(String(m.scope?.sourceQuoteSha256||'').slice(0,12))+'…':'';return esc(label)+' / '+esc(identity)+(m.sourceVersion&&m.sourceVersion!==m.sourceId?' / '+esc(m.sourceVersion):'')+'；访问：'+esc(m.sourceAccessStatus||'not_required')+(m.sourceAccessExpiresAt?' 至 '+esc(formatTime(m.sourceAccessExpiresAt)):'')+'；置信度：'+esc(m.confidence==null?'未知':m.confidence)+historical}
    function memoryRows(){return state.memories.map(m=>{const conflictIds=m.conflict?.conflictIds||[];const conflicts=m.conflict?.conflicts||[];const sourceReady=m.sourceType!=='dingtalk_message'||m.sourceEvidence?.status==='available';const conflictEvidence=conflictIds.length?'<div class="notice"><strong>与现有正式记忆冲突，不能普通确认。</strong>'+(conflicts.length?conflicts.map(old=>'<div>现有：'+esc(old.statement)+' <button data-action="memory-replace" data-id="'+esc(m.id)+'" data-supersedes="'+esc(old.id)+'">明确替代这条旧记忆</button></div>').join(''):'<div>旧事实暂时无法载入，请刷新后再处理，当前不会允许确认。</div>')+'</div>':'';const confirmButton=m.status==='proposed'&&sourceReady&&conflictIds.length===0?'<button data-action="memory-confirm" data-id="'+esc(m.id)+'">确认新记忆</button>':'';return '<tr><td>'+tag(m.status)+'</td><td>'+esc(m.type)+'</td><td>'+esc(m.subject)+'</td><td class="preview"><strong>候选：</strong>'+esc(m.statement)+'<br><small>来源：'+memorySourceDetails(m)+'</small>'+(m.sourceType==='dingtalk_message'?'<div class="source-evidence"><strong>原消息证据：</strong>'+(m.sourceEvidence?.status==='available'?esc(m.sourceEvidence.excerpt||'（空消息）')+'<br><small>'+esc(m.sourceEvidence.senderName||'未知发送人')+(m.sourceEvidence.occurredAt?' · '+esc(formatTime(m.sourceEvidence.occurredAt)):'')+'</small>':'<span class="tag bad">来源不可核对，禁止确认</span>')+'</div>':'')+conflictEvidence+'</td><td>'+esc(m.sensitivity)+'</td><td><div class="row-actions">'+confirmButton+(['proposed','confirmed'].includes(m.status)?'<button data-action="memory-revoke" data-id="'+esc(m.id)+'">撤销</button>':'')+'</div></td></tr>'})}
    function table(headers,rows){if(!rows.length)return '<div class="empty">暂无记录</div>';return '<div class="table-wrap"><table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>'}
    async function load(){el('content').innerHTML='<div class="skeleton"></div><div class="skeleton"></div>';try{if(state.view==='overview'||state.view==='health')state.overview=await api('/api/overview');else if(state.view==='tasks')state.tasks=(await api('/api/tasks')).items;else if(state.view==='plans')state.plans=(await api('/api/plans')).items;else if(state.view==='takeover')state.takeovers=(await api('/api/takeover')).items;else if(state.view==='quality')state.quality=await api('/api/quality');else if(state.view==='operations')state.operations=await api('/api/operations');else if(state.view==='targets')state.targets=await api('/api/targets');else if(state.view==='capabilities')state.capabilities=await api('/api/capabilities');else if(state.view==='scoped-pauses')state.scopedPauses=(await api('/api/scoped-pauses')).items;else if(state.view==='privacy')state.privacyPreview=null;else state.memories=(await api('/api/memories')).items;render();renderQuality();renderOperations();renderScopedPauses();renderGlobalCapabilities();renderPlanControls();renderTaskReviewControls();el('updated').textContent='更新于 '+new Date().toLocaleTimeString()}catch(e){if(String(e.message).includes('unauthorized'))return logout();el('content').innerHTML='<div class="error" role="alert">'+esc(e.message)+'</div>'}}
    function optionButtons(options,action,selected,columns=''){const disabled=state.qualitySession.submitting?' disabled':'';return '<div class="review-options '+columns+'">'+options.map(x=>'<button type="button" class="btn review-option" data-action="'+action+'" data-value="'+esc(x[0])+'" aria-pressed="'+String(selected===x[0])+'"'+disabled+'>'+esc(x[1])+'</button>').join('')+'</div>'}
    function qualityReviewWorkflow(current){
      syncQualityReview(current);
      const f=state.qualitySession;
      const expected=f.expectedShouldReply;
      const responseComplete=typeof expected==='boolean';
      const draftApplicable=responseComplete&&expected===true&&current.shouldReply===true&&String(current.draft||'').trim().length>0;
      const draftActive=f.stage==='draft';
      const steps='<div class="review-steps" aria-label="标注进度"><div class="review-step '+(draftActive?'complete':'active')+'"><strong>回应必要性</strong><span>'+(responseComplete?(expected?'需要回应':'无需回应'):'等待判断')+'</span></div><div class="review-step '+(draftActive?'active':'')+'"><strong>草稿质量</strong><span>'+(draftApplicable?(draftActive?'等待评价':'下一步'):'按情况启用')+'</span></div></div>';
      let form='';
      if(f.stage==='response'){
        const disabled=f.submitting?' disabled':'';form='<fieldset class="review-form" aria-busy="'+String(f.submitting)+'"><legend>这条消息是否需要得到回应？</legend><div class="review-choice"><button type="button" class="btn review-option" data-action="quality-response" data-value="reply" aria-pressed="false"'+disabled+'>需要回应</button><button type="button" class="btn review-option" data-action="quality-response" data-value="no-reply" aria-pressed="false"'+disabled+'>无需回应</button></div></fieldset>';
      }else if(f.stage==='response_reason'){
        form='<fieldset class="review-form"><legend>请选择回应判断分歧的主要原因</legend>'+optionButtons(reviewReasonOptions,'quality-response-reason',f.responseReasonCode)+'</fieldset>'+(f.responseReasonCode?'<label class="review-detail"><span>补充说明（可选，最多 500 字）</span><textarea id="quality-detail" maxlength="500" placeholder="只写帮助复盘的信息，不粘贴额外敏感内容"></textarea></label>':'')+reviewSubmitControls(Boolean(f.responseReasonCode));
      }else if(f.stage==='draft'){
        const draftOptions=[['usable','可直接使用'],['needs_revision','需要修改'],['unsafe','不安全']];
        const needsDraftReason=['needs_revision','unsafe'].includes(f.draftAssessment);
        form='<fieldset class="review-form"><legend>这份拟回复本身是否可用？</legend>'+optionButtons(draftOptions,'quality-draft',f.draftAssessment,'three')+'</fieldset>'+(needsDraftReason?'<fieldset class="review-form"><legend>请选择草稿问题的主要原因</legend>'+optionButtons(draftReasonOptions,'quality-draft-reason',f.draftReasonCode)+'</fieldset>':'')+((f.draftAssessment==='usable'||f.draftReasonCode)?'<label class="review-detail"><span>补充说明（可选，最多 500 字）</span><textarea id="quality-detail" maxlength="500" placeholder="说明需要调整的位置，不要补充无关个人信息"></textarea></label>':'')+reviewSubmitControls(Boolean(f.draftAssessment)&&(!needsDraftReason||Boolean(f.draftReasonCode)));
      }
      return steps+form+(f.error?'<p class="review-inline-error" role="alert">'+esc(f.error)+'</p>':'')+'<p class="hint"><strong>回应判断和草稿质量是两件事。</strong>标注只用于评估，不会批准草稿，也不会触发发送。</p>';
    }
    function reviewSubmitControls(enabled){const busy=state.qualitySession.submitting;return '<div class="review-submit" aria-busy="'+String(busy)+'"><div class="left"><button type="button" class="btn" data-action="quality-back"'+(busy?' disabled':'')+'>返回修改回应判断</button><button type="button" class="btn" data-action="quality-cancel"'+(busy?' disabled':'')+'>取消</button></div><div class="right"><button type="button" class="btn primary" data-action="quality-submit"'+(!enabled||busy?' disabled':'')+'>'+(busy?'正在保存':'保存并进入下一条')+'</button></div></div>'}
    async function submitQualityReview(current){
      const f=state.qualitySession;
      const expected=f.expectedShouldReply;
      if(typeof expected!=='boolean')throw new Error('请先判断是否需要回应');
      const disagrees=expected!==current.shouldReply;
      if(disagrees&&!f.responseReasonCode)throw new Error('请选择回应判断分歧原因');
      const needsDraft=expected===true&&current.shouldReply===true&&String(current.draft||'').trim().length>0;
      if(needsDraft&&!f.draftAssessment)throw new Error('请选择草稿质量');
      if(['needs_revision','unsafe'].includes(f.draftAssessment)&&!f.draftReasonCode)throw new Error('请选择草稿问题原因');
      const body={expectedShouldReply:expected,decisionSha256:current.decisionSha256,detail:String(el('quality-detail')?.value||'').trim()};
      if(disagrees)body.responseReasonCode=f.responseReasonCode;
      if(needsDraft){body.draftAssessment=f.draftAssessment;body.draftSha256=current.draftSha256;if(f.draftReasonCode)body.draftReasonCode=f.draftReasonCode}
      f.submitting=true;f.error='';renderQuality();
      try{await api('/api/tasks/'+encodeURIComponent(current.id)+'/review',{method:'POST',body,write:true});f.completed+=1;resetQualityReview();state.quality=await api('/api/quality');renderQuality();el('updated').textContent='更新于 '+new Date().toLocaleTimeString()}catch(error){f.submitting=false;f.error=error.message;renderQuality()}
    }
    async function handleQualityAction(action,value){
      const current=(state.quality?.queue||[])[0];
      if(!current)throw new Error('当前没有待复核消息');
      syncQualityReview(current);const f=state.qualitySession;
      if(f.submitting)return;
      f.error='';
      if(action==='quality-response'){
        f.expectedShouldReply=value==='reply';f.responseReasonCode=null;f.draftAssessment=null;f.draftReasonCode=null;
        if(f.expectedShouldReply!==current.shouldReply){f.stage='response_reason';renderQuality();return}
        if(f.expectedShouldReply===true&&String(current.draft||'').trim().length>0){f.stage='draft';renderQuality();return}
        await submitQualityReview(current);return;
      }
      if(action==='quality-response-reason'){f.responseReasonCode=value;renderQuality();return}
      if(action==='quality-draft'){f.draftAssessment=value;f.draftReasonCode=null;renderQuality();return}
      if(action==='quality-draft-reason'){f.draftReasonCode=value;renderQuality();return}
      if(action==='quality-back'||action==='quality-cancel'){resetQualityReview(current.id);renderQuality();return}
      if(action==='quality-submit')await submitQualityReview(current);
    }
    function renderQuality(){
      if(state.view!=='quality')return;
      const q=state.quality;
      const current=(q.queue||[])[0];
      const percent=(value)=>value==null?'样本不足':(value*100).toFixed(1)+'%';
      const remaining=Math.max(0,q.thresholds.minimumSamples-q.reviewed);
      const breakdown=(q.breakdown||[]).map(x=>'<tr><td>'+esc(x.dimension)+'</td><td>'+esc(x.label)+'</td><td>'+esc(x.reviewed)+'</td><td>'+esc(percent(x.accuracy))+'</td><td>'+esc(percent(x.replyAccuracy))+'</td><td>'+esc(percent(x.noReplyAccuracy))+'</td><td>'+esc(x.falseReplyRecommendations)+'</td><td>'+esc(x.missedReplyNeeds)+'</td></tr>');
      const disagreementReasons=(q.disagreementReasons||[]).map(x=>'<tr><td>'+esc(x.label)+'</td><td>'+esc(x.count)+'</td></tr>');
      const draftReasons=(q.draftQuality?.reasons||[]).map(x=>'<tr><td>'+esc(x.label)+'</td><td>'+esc(x.count)+'</td></tr>');
      const coverage=(q.coverage?.rows||[]).map(x=>'<tr><td>'+esc(x.dimension)+'</td><td>'+esc(x.label)+'</td><td>'+esc(x.eligible)+'</td><td>'+esc(x.reviewed)+'</td><td>'+esc(x.required)+'</td><td><span class="tag '+(x.passed?'ok':'bad')+'">'+(x.passed?'覆盖':'待补')+'</span></td></tr>');
      const queue=(q.queue||[]).slice(1,10).map(t=>'<tr><td>'+esc(t.priorityReasons.join('、'))+'</td><td>'+esc(t.senderName||'未知')+'</td><td>'+esc(t.contentPreview||'')+'</td><td>'+esc(t.shouldReply?'建议回复':'建议不回复')+'</td></tr>');
      const focus=current?'<section class="section"><div class="section-head"><h2>连续人工复核</h2><span class="tag warn">待复核</span></div><div class="review-card"><div class="review-progress"><strong>本轮已完成 '+esc(state.qualitySession.completed)+' 条</strong><span class="sub" role="status">回应判断门槛还需 '+esc(remaining)+' 条，当前队列 '+esc(q.queue.length)+' 条</span></div><div class="review-meta"><span>选择原因：'+esc(current.priorityReasons.join('、'))+'</span><span>对象：'+esc(current.senderName||'未知')+'</span><span>AI 判断：'+esc(current.shouldReply?'建议回应':'建议不回应')+'</span><span>风险：'+esc(current.riskLevel||'未标注')+'</span></div><div class="review-message">'+esc(current.reviewContent||current.contentPreview||'')+'</div>'+(current.reason?'<p><strong>判断原因：</strong>'+esc(current.reason)+'</p>':'')+(current.shouldReply&&current.draft?'<div><strong>拟回复：</strong><p class="review-draft">'+esc(current.draft)+'</p></div>':'')+qualityReviewWorkflow(current)+'</div></section>':'<section class="section"><div class="empty"><strong>当前没有待复核消息</strong><br><span class="hint">新消息或待补草稿评价会自动进入队列。</span></div></section>';
      el('content').innerHTML=focus+'<section class="section"><div class="section-head"><h2>影子判断质量门槛</h2><span class="sub">回应判断还需 '+remaining+' 条；'+(q.accepted?'已达到放量门槛':'尚未达到放量门槛')+'</span></div>'+table(['指标','当前值','门槛','结果'],[['有效回应判断',q.reviewed,q.thresholds.minimumSamples,q.gates.enoughSamples],['分层样本覆盖',q.coverage?.accepted?'完整':'待补','全部分层达标',q.gates.coverage],['建议回复准确率',percent(q.replyAccuracy),percent(q.thresholds.minimumReplyAccuracy),q.gates.replyAccuracy],['建议不回复准确率',percent(q.noReplyAccuracy),percent(q.thresholds.minimumNoReplyAccuracy),q.gates.noReplyAccuracy],['高风险错误回复建议',q.highRiskFalseReplyRecommendations,0,q.gates.noHighRiskFalseReplyRecommendations],['草稿评价样本',q.draftQuality?.reviewed||0,q.thresholds.minimumDraftSamples,q.gates.enoughDraftSamples],['草稿可直接使用率',percent(q.draftQuality?.usabilityRate),percent(q.thresholds.minimumDraftUsability),q.gates.draftUsability],['不安全草稿',q.draftQuality?.unsafe||0,0,q.gates.noUnsafeDrafts]].map(x=>'<tr><td>'+esc(x[0])+'</td><td>'+esc(x[1])+'</td><td>'+esc(x[2])+'</td><td><span class="tag '+(x[3]?'ok':'bad')+'">'+(x[3]?'通过':'未通过')+'</span></td></tr>'))+'</section><section class="section"><div class="section-head"><h2>草稿质量</h2><span class="sub">可直接使用 '+esc(q.draftQuality?.usable||0)+'；需要修改 '+esc(q.draftQuality?.needsRevision||0)+'；不安全 '+esc(q.draftQuality?.unsafe||0)+'</span></div>'+table(['草稿问题类别','数量'],draftReasons)+'</section><section class="section"><div class="section-head"><h2>样本覆盖进度</h2><span class="sub">判断类别、会话类型和判断来源分别达标</span></div>'+table(['维度','分组','可标注','已标注','最低要求','状态'],coverage)+'</section><section class="section"><div class="section-head"><h2>分层误判</h2><span class="sub">历史自由文本分歧先重新确认，不计入准确率</span></div>'+table(['维度','分组','样本','准确率','建议回复准确率','建议不回复准确率','误建议回复','漏回复'],breakdown)+'</section><section class="section"><div class="section-head"><h2>回应分歧原因</h2><span class="sub">只展示结构化类别和数量，不展示消息或补充说明</span></div>'+table(['原因类别','数量'],disagreementReasons)+'</section><section class="section"><div class="section-head"><h2>后续复核队列</h2><span class="sub">优先补齐历史分歧和草稿评价，再进行覆盖抽样</span></div>'+table(['选择原因','对象','消息预览','AI 判断'],queue)+'</section>';
    }
    function acceptancePanel(a){const labels={serviceHealth:'运行健康',decisionQuality:'人工判断与草稿质量',operationalDataComplete:'最近 24 小时统计完整',availability:'滚动 30 天可用性',messageDetection:'消息发现 P95',messageCoverage:'消息源漏检率',lowRiskSuccess:'低风险任务成功率',lowRiskDuration:'草稿产出 P95',duplicateSideEffects:'无重复副作用',unknownSideEffects:'无未知副作用',sideEffectAudit:'副作用回读审计',memoryConflicts:'无正式记忆冲突'};const rows=Object.entries(a?.gates||{}).map(([key,passed])=>'<tr><td>'+esc(labels[key]||key)+'</td><td><span class="tag '+(passed?'ok':'bad')+'">'+(passed?'通过':'未通过')+'</span></td></tr>');return '<section class="section"><div class="section-head"><h2>业务放量总门禁</h2><span class="tag '+(a?.accepted?'ok':'bad')+'">'+(a?.accepted?'全部通过':'禁止放量')+'</span></div><p class="section-hint hint">这里统一汇总运行健康、人工质量和长期 SLO；未知值也按未通过处理。即使全部通过，开启自动发送或计划执行仍需单独审批。</p>'+table(['门禁','状态'],rows)+'</section>'}
    function renderOperations(){if(state.view!=='operations')return;const o=state.operations;const coverage=o.messageCoverage;const availability=o.availability;const duration=(v)=>v==null?'样本不足':v<1000?v+' 毫秒':(v/1000).toFixed(1)+' 秒';const percent=(v)=>v==null?'样本不足':(v*100).toFixed(1)+'%';const result=(v)=>v==='observe'?'<span class="tag">仅观察</span>':v==null?'<span class="tag warn">样本不足</span>':'<span class="tag '+(v?'ok':'bad')+'">'+(v?'达标':'未达标')+'</span>';const rows=[['入口月度可用性',percent(availability?.availability),'≥ 99.5%',availability?.targetMet??null,availability?.recordedSamples??0],['消息发现 P95',duration(o.messageDetection.p95Ms),'< 5 秒',o.messageDetection.targetMet,o.messageDetection.samples],['真实漏检率',percent(coverage?.observedMissRate),'< 0.1%',coverage?.targetMet??null,coverage?.sourceMessages??0],['低风险任务成功率',percent(o.lowRiskTasks.successRate),'≥ 95%',o.lowRiskTasks.successRateTargetMet,o.lowRiskTasks.samples],['草稿产出耗时 P95',duration(o.lowRiskTasks.durationP95Ms),'< 2 分钟',o.lowRiskTasks.durationTargetMet,o.lowRiskTasks.durationSamples],['任务全流程耗时 P95',duration(o.lowRiskTasks.lifecycleP95Ms),'观察项','observe',o.lowRiskTasks.lifecycleSamples],['审批等待 P95',duration(o.approvalWait.p95Ms),'观察项','observe',o.approvalWait.samples],['副作用审计覆盖率',percent(o.reliability.sideEffectAuditCoverage),'100%',o.reliability.sideEffectAuditCoverage==null?null:o.reliability.sideEffectAuditCoverage===1,o.reliability.completedSideEffects]];el('content').innerHTML=acceptancePanel(o.businessAcceptance)+(o.window.dataComplete?'':'<div class="notice">当前 24 小时数据超过单次统计上限，结果不完整，不能用于 SLO 结论。</div>')+(availability&&!availability.windowComplete?'<div class="notice">入口可用性尚未积满 30 天，仅展示观察值；缺失探针按不可用计算。当前窗口覆盖 '+percent(availability.trackingCoverage)+'。</div>':'')+(coverage&&!coverage.dataComplete?'<div class="notice">消息源对账超过单次上限，真实漏检率仅供观察，不能用于 SLO 结论。</div>':'')+'<section class="section"><div class="section-head"><h2>运营 SLO</h2><span class="sub">入口可用性按月统计，其余为最近 24 小时；无样本不等于达标</span></div>'+table(['指标','当前值','目标','判断','样本'],rows.map(x=>'<tr><td>'+esc(x[0])+'</td><td>'+esc(x[1])+'</td><td>'+esc(x[2])+'</td><td>'+result(x[3])+'</td><td>'+esc(x[4])+'</td></tr>'))+'</section><section class="section"><div class="section-head"><h2>可靠性事件</h2></div>'+table(['入口缺测分钟','对账发现漏项','对账已修复','仍缺失','重复副作用','未知副作用','Codex 超时','死亡任务'],['<tr><td>'+esc(availability?.missingSamples??'未采样')+'</td><td>'+esc(coverage?.missedBeforeRepair??'未对账')+'</td><td>'+esc(coverage?.repairedMessages??'未对账')+'</td><td>'+esc(coverage?.remainingMissing??'未对账')+'</td><td>'+esc(o.reliability.duplicateSideEffects)+'</td><td>'+esc(o.reliability.unknownSideEffects)+'</td><td>'+esc(o.reliability.codexTimeouts)+'</td><td>'+esc(o.reliability.deadTasks)+'</td></tr>'])+'</section>'}
    function renderTargets(){const snapshot=state.targets||{counts:{users:0,groups:0},items:[]};const rows=(snapshot.items||[]).map((x,i)=>'<tr><td>'+esc(x.kind==='user'?'私聊联系人':'群聊')+'</td><td><code>'+esc(x.fingerprint)+'</code></td><td>'+esc(x.kind==='user'?'白名单中的新私聊消息':'白名单群中结构化确认 @我')+'</td><td><span class="tag '+(x.replyEnabled?'ok':'warn')+'">'+(x.replyEnabled?'审批后可发送':'仅判断和草稿')+'</span></td><td><span class="tag '+(x.paused?'bad':'ok')+'">'+(x.paused?'已暂停':'监听中')+'</span></td><td><button data-action="'+(x.paused?'target-resume':'target-pause')+'" data-id="'+i+'">'+(x.paused?'恢复':'暂停')+'</button></td></tr>');el('content').innerHTML='<div class="notice">这里只显示 HMAC 指纹，不返回真实钉钉编号。新增、删除或替换监听目标仍必须使用受控命令并重载服务。</div><div class="grid"><div class="metric">私聊联系人<strong>'+Number(snapshot.counts?.users||0)+'</strong></div><div class="metric">群聊<strong>'+Number(snapshot.counts?.groups||0)+'</strong></div><div class="metric">群聊触发<strong>@我</strong></div><div class="metric">被 @ 后<strong>仍会判断</strong></div></div><section class="section"><div class="section-head"><h2>当前监听白名单</h2><span class="sub">指纹用于核对配置身份，不是钉钉编号</span></div>'+table(['类型','身份指纹','进入判断条件','回复能力','状态','操作'],rows)+'</section><section class="section"><div class="section-head"><h2>回复规则</h2></div><div class="section-body"><p>私聊：白名单消息进入判断；“收到、谢谢、不用回”等闭环消息保持安静。</p><p>群聊：只有白名单群中结构化确认的 <strong>@我</strong> 消息进入判断；仅抄送、公告、闲聊、别人已回答或没有明确问题时仍不回复。</p><p class="hint">暂停只阻止新的草稿和已批准发送，不删除历史数据，也不会自动重放暂停期间的外部动作。</p></div></section>'}
    function renderScopedPauses(){if(state.view!=='scoped-pauses')return;const labels={contact:'联系人',group:'群聊',project:'项目',capability:'能力'};const rows=state.scopedPauses.map((x,i)=>'<tr><td>'+esc(labels[x.type]||x.type)+'</td><td>'+esc(x.value)+'</td><td>'+esc(x.reason||'-')+'</td><td>'+esc(x.actor||'-')+'</td><td>'+esc(formatTime(x.updatedAt))+'</td><td><button data-action="scope-resume" data-id="'+i+'">恢复</button></td></tr>');el('content').innerHTML='<section class="section"><div class="section-head"><h2>局部暂停</h2><div class="row-actions"><button data-action="scope-add" data-id="contact">暂停联系人</button><button data-action="scope-add" data-id="group">暂停群聊</button><button data-action="scope-add" data-id="project">暂停项目</button><button data-action="scope-add" data-id="capability">暂停能力</button></div></div><p class="hint section-hint">只能暂停已配置联系人、群聊、已登记项目或已知能力。恢复不会自动重放副作用。</p>'+table(['范围','对象','原因','操作人','时间','操作'],rows)+'</section>'}
    function renderPrivacy(){const p=state.privacyPreview;const labels={person:'人员',project:'项目',time:'截止时间'};const categories={tasks:'任务',messages:'消息',workPlans:'工作计划',memories:'正式记忆',capabilityBudgets:'能力次数预算',auditEvents:'审计事件',identityReferences:'身份引用',scopedPauses:'暂停规则'};const rows=p?Object.entries(categories).map(([key,label])=>'<tr><td>'+label+'</td><td>'+Number(p.counts?.[key]||0)+'</td><td>'+Number(p.blocked?.[key]||0)+'</td></tr>'):[];const result=!p?'':('<section class="section"><div class="section-head"><h2>预览结果</h2><span class="tag '+(p.blockedTotal?'bad':p.eligibleTotal?'warn':'ok')+'">'+(p.blockedTotal?'存在阻塞':p.eligibleTotal?'允许进入命令行确认':'没有可删除数据')+'</span></div><div class="section-body"><p><strong>范围类型：</strong>'+esc(labels[p.selector?.type]||'未知')+'；<strong>脱敏指纹：</strong><code>'+esc(p.selector?.fingerprint||'-')+'</code></p><p><strong>可擦除记录：</strong>'+Number(p.eligibleTotal||0)+'；<strong>阻塞记录：</strong>'+Number(p.blockedTotal||0)+'</p>'+table(['数据类别','可擦除','阻塞'],rows)+(p.confirmation?'<p><strong>快照确认值：</strong><code class="privacy-code">'+esc(p.confirmation)+'</code></p><div class="row-actions"><button data-action="privacy-copy">复制确认值</button></div><p class="hint">确认值只对当前数据快照有效；任何相关数据变化后都必须重新预览。</p>':'<p class="hint">'+(p.blockedTotal?'请先完成或取消阻塞记录，再重新预览。':'当前没有符合条件且可擦除的数据。')+'</p>')+'<p class="hint">快照摘要：<code>'+esc(p.snapshotDigest||'-')+'</code></p></div></section>');el('content').innerHTML='<div class="notice"><strong>这里只预览，不会删除数据。</strong>真正执行必须通过命令行，并重新提交同一范围和快照确认值；管理台没有删除接口。</div><section class="section"><div class="section-head"><h2>选择一个数据范围</h2><span class="sub">范围值不会保存在页面状态或出现在预览结果中</span></div><div class="privacy-form"><label class="field"><span>范围类型</span><select id="privacy-type"><option value="person">人员</option><option value="project">项目</option><option value="time">截止时间</option></select></label><label class="field"><span>范围值</span><input id="privacy-value" type="text" autocomplete="off" placeholder="输入钉钉用户编号"></label><button class="btn primary" data-action="privacy-preview">生成只读预览</button></div><p class="hint section-hint">预览涉及敏感范围扫描，因此需要只读令牌和写入令牌；它不会执行数据库写入。</p></section>'+result}
    function syncPrivacyInput(clear=false){const type=el('privacy-type');const input=el('privacy-value');if(!type||!input)return;if(clear)input.value='';input.type=type.value==='time'?'datetime-local':'text';input.placeholder=type.value==='person'?'输入钉钉用户编号':type.value==='project'?'输入项目编号':'选择本地截止时间'}
    function renderGlobalCapabilities(){if(state.view!=='capabilities')return;const rows=(state.capabilities.global||[]).map(x=>'<tr><td>'+esc(x.name)+'</td><td><span class="tag '+(x.enabled?'ok':'warn')+'">'+(x.enabled?'已开启':'已关闭')+'</span></td></tr>');el('content').insertAdjacentHTML('afterbegin','<section class="section"><div class="section-head"><h2>全局能力开关</h2><span class="sub">项目授权不能覆盖全局关闭</span></div>'+table(['能力','状态'],rows)+'</section>')}
    function renderPlanControls(){if(state.view!=='plans')return;const rows=el('content').querySelectorAll('tbody tr');state.plans.forEach((plan,index)=>{const actions=rows[index]?.querySelector('.row-actions');if(!actions)return;if(['awaiting_approval','rejected'].includes(plan.status)){const revise=document.createElement('button');revise.dataset.action='plan-revise';revise.dataset.id=plan.id;revise.textContent='修订';actions.append(revise)}if(['ready','awaiting_approval','approved','executing','verifying'].includes(plan.status)){const cancel=document.createElement('button');cancel.dataset.action='plan-cancel';cancel.dataset.id=plan.id;cancel.textContent=plan.status==='executing'||plan.status==='verifying'?'请求停止':'取消';actions.append(cancel)}})}
    function renderTaskReviewControls(){if(state.view!=='tasks')return;const rows=el('content').querySelectorAll('tbody tr');state.tasks.forEach((task,index)=>{if(typeof task.shouldReply!=='boolean')return;const actions=rows[index]?.querySelector('.row-actions');if(!actions)return;if(typeof task.expectedShouldReply==='boolean'){const current=document.createElement('span');current.className='tag ok';current.textContent='已标注：'+(task.expectedShouldReply?'需要回应':'无需回应');actions.append(current)}else{const hint=document.createElement('span');hint.className='task-review-hint';hint.textContent='请到“判断质量”统一标注';actions.append(hint)}})}
    function taskDetails(t){return '<details><summary>'+esc(t.contentPreview||'查看原消息')+'</summary><p><strong>原消息：</strong>'+esc(t.reviewContent||t.contentPreview||'-')+'</p><p><strong>实际回复草稿：</strong>'+esc(t.draft||'-')+'</p><p><strong>风险：</strong>'+esc(t.riskLevel||'-')+'；'+esc(t.reason||'未提供原因')+'</p>'+(t.needsInformation?'<p><strong>后续：</strong>追问发送成功后等待对方补充信息</p>':'')+(t.continuationOfTaskId?'<p><strong>任务关系：</strong>'+(t.relatedToWaitingTask?'已确认接续原任务':'正在核对是否接续原任务')+'</p>':'')+(t.failureCode?'<p><strong>失败分类：</strong>'+esc(failureLabel(t.failureCode))+' <span class="sub">('+esc(t.failureCode)+')</span></p>':'')+'<p class="sub">草稿哈希 '+esc(t.draftSha256||'-')+'</p></details>'}
    function takeoverDetails(p){const t=p.takeover||{};const s=t.currentStep;return '<details open><summary>'+esc(s?s.description:'暂无当前步骤')+'</summary><p><strong>当前能力：</strong>'+esc(s?.capability||'-')+'；<strong>步骤状态：</strong>'+esc(s?.status||'-')+'</p><p><strong>安全边界：</strong>'+(s?.sideEffect?'存在副作用':'无外部副作用')+'；'+(s?.interruptible?'可确认中断':'需安全收尾')+'</p><p><strong>已保存证据：</strong>'+esc(s?.verification||s?.evidenceKind||'暂无')+(s?.terminationSignal?'；终止信号 '+esc(s.terminationSignal):'')+'</p><p><strong>人工交接：</strong>'+esc(t.handoffAction||'-')+'</p><p class="sub">进度 '+esc(t.completedSteps||0)+' / '+esc(t.totalSteps||0)+(t.leaseExpiresAt?'；租约到期 '+esc(formatTime(t.leaseExpiresAt)):'')+'</p></details>'}
    function planDetails(p){const steps=(p.steps||[]).map((s,i)=>{const x=s.execution;const execution=x?'<br><span class="sub">执行状态：'+esc(x.status||'-')+'；证据：'+esc(x.verification||x.evidenceKind||'-')+(x.terminationSignal?'；终止信号：'+esc(x.terminationSignal):'')+(x.error?'；结果：'+esc(x.error):'')+'</span>':'';return '<li><strong>'+esc((i+1)+'. '+s.capability)+'</strong> '+esc(s.description||'')+'<br><span class="sub">目录：'+esc(s.workingDirectory||'-')+'</span><br>输入：<code>'+esc(JSON.stringify(s.inputs||{}))+'</code><br>验收：'+esc(s.expectedEvidence||'-')+'<br>回滚：'+esc(s.rollback||'-')+execution+'</li>'}).join('');const revision=p.supersedesWorkPlanId?'<p class="sub">修订自计划 '+esc(p.supersedesWorkPlanId)+'</p>':'';return '<details><summary>'+esc(p.objective||'查看完整计划')+'</summary><ol>'+steps+'</ol>'+revision+'<p class="sub">计划哈希 '+esc(p.planHash||'-')+'</p></details>'}
    function render(){const c=el('content');if(state.view==='overview'){const o=state.overview;const tasks=o.taskCounts||{};const plans=o.planCounts||{};c.innerHTML='<div class="statusbar"><span class="dot '+(o.ready?'ok':'bad')+'"></span><strong>'+(o.ready?'运行正常':'需要处理')+'</strong><span class="sub">'+(o.paused?'系统已暂停':'系统运行中')+'</span><span class="spacer"></span><span>'+esc(o.sendMode)+'</span></div><div class="grid"><div class="metric">待审批草稿<strong>'+Number(tasks.awaiting_approval||0)+'</strong></div><div class="metric">等待补充信息<strong>'+Number(tasks.waiting_information||0)+'</strong></div><div class="metric">异常任务<strong>'+Number((tasks.dead||0)+(tasks.send_unknown||0))+'</strong></div><div class="metric">异常计划<strong>'+Number(plans.failed||0)+'</strong></div><div class="metric">授权项目<strong>'+Number(o.projectCount||0)+'</strong></div><div class="metric">已确认记忆<strong>'+Number(o.confirmedMemoryCount||0)+'</strong></div></div><section class="section"><div class="section-head"><h2>健康检查</h2></div>'+checks(o.checks)+'</section>'}else if(state.view==='health'){c.innerHTML='<section class="section"><div class="section-head"><h2>完整运行状态</h2></div>'+checks(state.overview.checks)+'</section>'}else if(state.view==='tasks'){c.innerHTML='<section class="section"><div class="section-head"><h2>最近任务</h2><span class="sub">批准前核对实际回复内容</span></div>'+table(['状态','发起人','原消息与草稿','时间','操作'],state.tasks.map(t=>'<tr><td>'+tag(t.status)+'</td><td>'+esc(t.senderName||'未知')+'</td><td>'+taskDetails(t)+'</td><td>'+esc(formatTime(t.createdAt))+'</td><td><div class="row-actions">'+(t.status==='awaiting_approval'?'<button data-action="task-approve" data-id="'+esc(t.id)+'">批准</button><button data-action="task-reject" data-id="'+esc(t.id)+'">拒绝</button>':'')+(t.status==='dead'?'<button data-action="task-retry" data-id="'+esc(t.id)+'">重试</button><button data-action="task-dismiss" data-id="'+esc(t.id)+'">关闭</button>':'')+'</div></td></tr>'))+'</section>'}else if(state.view==='plans'){c.innerHTML='<section class="section"><div class="section-head"><h2>工作计划（批准后可由执行器领取）</h2><span class="sub">L3/L4 需二次输入哈希尾码</span></div>'+table(['状态','项目','完整计划','风险','时间','操作'],state.plans.map(p=>'<tr><td>'+tag(p.status)+'</td><td>'+esc(p.projectId)+'</td><td>'+planDetails(p)+'</td><td>'+esc(p.maxLevel)+'</td><td>'+esc(formatTime(p.updatedAt))+'</td><td><div class="row-actions">'+(p.status==='awaiting_approval'?'<button data-action="plan-approve" data-id="'+esc(p.id)+'">批准</button><button data-action="plan-reject" data-id="'+esc(p.id)+'">拒绝</button>':'')+'</div></td></tr>'))+'</section>'}else if(state.view==='takeover'){c.innerHTML='<section class="section"><div class="section-head"><h2>人工接管</h2><span class="sub">先确认实际状态，再继续或重建计划</span></div>'+table(['接管状态','项目与计划','当前步骤和证据','更新时间','操作'],state.takeovers.map(p=>'<tr><td><span class="tag '+(['lease_expired','needs_reconciliation'].includes(p.takeover.state)?'bad':['safe_finishing','interrupt_requested','side_effect_running'].includes(p.takeover.state)?'warn':'ok')+'">'+esc(p.takeover.stateLabel)+'</span></td><td><strong>'+esc(p.projectId)+'</strong><br>'+esc(p.objective)+'</td><td>'+takeoverDetails(p)+'</td><td>'+esc(formatTime(p.updatedAt))+'</td><td><div class="row-actions">'+(p.takeover.canRequestCancellation?'<button data-action="plan-cancel" data-id="'+esc(p.id)+'">请求停止</button>':'')+'</div></td></tr>'))+'</section>'}else if(state.view==='targets'){renderTargets()}else if(state.view==='capabilities'){const rows=state.capabilities.projects.flatMap(p=>p.capabilities.map(x=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.level)+'</td><td>'+tag(x.mode)+'</td><td>'+tag(x.available?'可用':'不可用')+'</td><td>'+esc(x.expiresAt?formatTime(x.expiresAt):'长期')+'</td></tr>'));const pending=state.capabilities.catalog.filter(x=>!x.implemented).map(x=>x.name).join('、')||'无';c.innerHTML='<section class="section"><div class="section-head"><h2>项目授权能力</h2><span class="sub">只读展示，不能在这里扩大权限</span></div>'+table(['项目','能力','风险','授权模式','当前状态','有效期'],rows)+'</section><section class="section"><div class="section-head"><h2>尚未接入适配器</h2></div><div class="empty">'+esc(pending)+'</div></section>'}else if(state.view==='privacy'){renderPrivacy()}else{c.innerHTML='<section class="section"><div class="section-head"><h2>记忆候选与正式记忆</h2></div>'+table(['状态','类型','主题','内容与来源','敏感度','操作'],memoryRows())+'</section>'}}
    function checks(c){const rows=[['数据库',c.database],['DWS 可执行',c.dwsExecutable],['Codex 可执行',c.codexExecutable],['系统未暂停',!c.paused],['无死亡任务',c.deadTasks===0],['无未知发送',c.unknownSends===0]];if(c.messageCoverage?.required)rows.push(['消息源对账',c.messageCoverage.healthy]);for(const [k,v] of Object.entries(c.heartbeats||{}))rows.push(['心跳 '+k,v.healthy]);for(const [k,v] of Object.entries(c.operationalChecks||{}))rows.push(['业务检查 '+k,v.healthy]);return table(['检查项','结果'],rows.map(([k,v])=>'<tr><td>'+esc(k)+'</td><td>'+tag(v?'正常':'异常')+'</td></tr>'))}
    const formatTime=(v)=>v?new Date(v).toLocaleString():'-';
    async function mutate(action,id,supersedesId){const task=state.tasks.find(x=>x.id===id);const plan=state.plans.find(x=>x.id===id)||state.takeovers.find(x=>x.id===id);if(action==='target-pause'||action==='target-resume'){const target=state.targets?.items?.[Number(id)];if(!target)throw new Error('监听范围已变化，请刷新');const paused=action==='target-pause';const reason=paused?(prompt('请输入暂停原因：')||''):'';if(!confirm((paused?'确认暂停':'确认恢复')+(target.kind==='user'?'该联系人':'该群聊')+'？'))return;await api('/api/targets/'+target.kind+'/'+target.fingerprint+'/pause',{method:'POST',body:{paused,reason},write:true});await load();return}if(action==='privacy-copy'){const value=state.privacyPreview?.confirmation;if(!value)return;try{if(!navigator.clipboard?.writeText)throw new Error('clipboard_unavailable');await navigator.clipboard.writeText(value);alert('确认值已复制')}catch{prompt('请复制确认值：',value)}return}if(action==='privacy-preview'){const type=el('privacy-type')?.value;const raw=String(el('privacy-value')?.value||'').trim();if(!raw)throw new Error('请输入要预览的范围值');let selector;if(type==='person')selector={personId:raw};else if(type==='project')selector={projectId:raw};else{const before=new Date(raw);if(Number.isNaN(before.getTime())||before>=new Date())throw new Error('截止时间必须是过去的有效时间');selector={before:before.toISOString()}}state.privacyPreview=await api('/api/privacy/preview',{method:'POST',body:selector,write:true});renderPrivacy();return}if(action==='scope-add'){const value=prompt('请输入要暂停的'+({contact:'联系人账号',group:'群聊编号',project:'项目编号',capability:'能力名称'}[id]||'对象')+'：');if(!value)return;const reason=prompt('请输入暂停原因：')||'';if(!confirm('确认暂停该范围？新的相关工作将等待恢复。'))return;await api('/api/scoped-pauses',{method:'POST',body:{type:id,value,paused:true,reason},write:true});await load();return}if(action==='scope-resume'){const scope=state.scopedPauses[Number(id)];if(!scope)throw new Error('暂停规则已变化，请刷新');if(!confirm('确认恢复 '+scope.value+'？恢复不会自动重放已经发生过的外部动作。'))return;await api('/api/scoped-pauses',{method:'POST',body:{type:scope.type,value:scope.value,paused:false},write:true});await load();return}if(action==='plan-revise'){if(!plan)throw new Error('计划状态已变化，请刷新');const text=prompt('修改目标或步骤 JSON。修订后旧计划立即失效，新计划必须重新审批。',JSON.stringify({objective:plan.objective,steps:plan.steps},null,2));if(text==null)return;let revised;try{revised=JSON.parse(text)}catch{throw new Error('计划 JSON 格式不正确')};if(typeof revised.objective!=='string'||!Array.isArray(revised.steps))throw new Error('修订内容必须包含 objective 和 steps');if(!confirm('确认提交修订？旧计划将标记为“已替代”，任何旧审批都不能复用。'))return;await api('/api/plans/'+encodeURIComponent(id)+'/revise',{method:'POST',body:{currentPlanHash:plan.planHash,plan:revised},write:true});await load();return}const map={
      'task-approve':['/api/tasks/'+encodeURIComponent(id)+'/decision',{decision:'approved',draftSha256:task?.draftSha256}],
      'task-reject':['/api/tasks/'+encodeURIComponent(id)+'/decision',{decision:'rejected'}],
      'task-retry':['/api/tasks/'+encodeURIComponent(id)+'/retry',{}],
      'task-dismiss':['/api/tasks/'+encodeURIComponent(id)+'/dismiss',{reason:'负责人确认不再重试'}],
      'plan-approve':['/api/plans/'+encodeURIComponent(id)+'/decision',{decision:'approved',planHash:plan?.planHash}],
      'plan-reject':['/api/plans/'+encodeURIComponent(id)+'/decision',{decision:'rejected'}],
      'plan-cancel':['/api/plans/'+encodeURIComponent(id)+'/cancel',{planHash:plan?.planHash}],
      'memory-confirm':['/api/memories/'+encodeURIComponent(id)+'/decision',{decision:'confirmed'}],
      'memory-replace':['/api/memories/'+encodeURIComponent(id)+'/decision',{decision:'replaced',supersedesId}],
      'memory-revoke':['/api/memories/'+encodeURIComponent(id)+'/decision',{decision:'revoked'}]};
      const item=map[action];if(!item)return;if(action==='task-approve'){if(!task)throw new Error('草稿已变化，请刷新后重新审核');const message='确认批准以下实际回复草稿？\\n\\n'+task.draft+'\\n\\n风险：'+(task.riskLevel||'未标注')+'；'+(task.reason||'未提供原因');if(!confirm(message))return}else if(action==='task-dismiss'){if(!task)throw new Error('任务状态已变化，请刷新');if(!confirm('确认关闭这条失败任务且不再自动重试？\\n\\n原消息：'+task.contentPreview))return}else if(action==='plan-approve'){if(!plan)throw new Error('计划已变化，请刷新后重新审核');const summary=(plan.steps||[]).map((s,i)=>(i+1)+'. '+s.capability+'：'+s.description+'\\n输入：'+JSON.stringify(s.inputs||{})+'\\n回滚：'+(s.rollback||'-')).join('\\n\\n');if(!confirm('确认批准以下完整计划？\\n\\n目标：'+plan.objective+'\\n\\n'+summary+'\\n\\n计划哈希：'+plan.planHash))return;if(['L3','L4'].includes(plan.maxLevel)){const suffix=String(plan.planHash||'').slice(-8);if(prompt('高风险计划，请输入计划哈希末 8 位确认：\\n'+suffix)!==suffix)return}}else if(action==='plan-cancel'){if(!plan)throw new Error('计划已变化，请刷新后重试');if(!confirm('确认取消计划？\\n\\n'+plan.objective+'\\n\\n执行中的当前步骤可能需要先安全结束，后续步骤不会继续。'))return}else if(action==='memory-replace'){const candidate=state.memories.find(x=>x.id===id);const previous=state.memories.find(x=>x.id===supersedesId)||candidate?.conflict?.conflicts?.find(x=>x.id===supersedesId);if(!candidate||!previous)throw new Error('记忆冲突已变化，请刷新');if(!confirm('这是纠正操作：将撤销旧记忆并启用新记忆。\\n\\n旧记忆：'+previous.statement+'\\n\\n新记忆：'+candidate.statement+'\\n\\n确认明确替代？'))return}else if(action==='memory-confirm'){const candidate=state.memories.find(x=>x.id===id);if(!candidate)throw new Error('记忆候选已变化，请刷新');if((candidate.conflict?.conflictIds||[]).length)throw new Error('冲突记忆必须使用“明确替代”操作');if(!confirm('确认将以下候选设为正式记忆？\\n\\n'+candidate.statement))return}else if(!confirm('确认执行此操作？'))return;await api(item[0],{method:'POST',body:item[1],write:true});await load()}
    async function login(){sessionStorage.setItem('ai-read',el('read-token').value);sessionStorage.setItem('ai-write',el('write-token').value);try{state.overview=await api('/api/overview');el('login').classList.add('hidden');el('app').classList.remove('hidden');render()}catch(e){el('login-error').textContent=e.message;el('login-error').classList.remove('hidden')}}
    function logout(){sessionStorage.removeItem('ai-read');sessionStorage.removeItem('ai-write');el('app').classList.add('hidden');el('login').classList.remove('hidden')}
    el('login-button').addEventListener('click',login);el('refresh').addEventListener('click',load);el('logout').addEventListener('click',logout);el('pause').addEventListener('click',async()=>{const paused=Boolean(state.overview?.paused);if(!confirm(paused?'确认恢复系统？':'确认暂停系统？'))return;await api('/api/system/'+(paused?'resume':'pause'),{method:'POST',body:{},write:true});await load()});document.querySelector('.nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));if(b.dataset.view==='quality'&&state.view!=='quality'){state.qualitySession.completed=0;resetQualityReview()}state.view=b.dataset.view;el('title').textContent=b.textContent;load()});el('content').addEventListener('change',e=>{if(e.target?.id==='privacy-type')syncPrivacyInput(true)});el('content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action.startsWith('quality-')){handleQualityAction(action,b.dataset.value).catch(error=>{state.qualitySession.error=error.message;state.qualitySession.submitting=false;renderQuality()});return}mutate(action,b.dataset.id,b.dataset.supersedes).catch(x=>alert(x.message))});
  </script>
</body></html>`;
